<?php
namespace App\Http\Requests\Mitra;
use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class SaveEventRequest extends FormRequest { public function authorize():bool{return $this->user()->can('event.manage');} public function rules():array{return ['name'=>'required|string|max:191','slug'=>['required','alpha_dash','max:191',Rule::unique('catalog_entities','slug')->ignore($this->route('event')?->id)],'category_id'=>'nullable|exists:categories,id','region_id'=>'required|exists:regions,id','description'=>'required|string|min:20','address'=>'required|string','event_type'=>'required|string|max:64','venue_name'=>'nullable|string|max:191','starts_at'=>'required|date|after:now','ends_at'=>'required|date|after:starts_at','registration_deadline'=>'nullable|date|before_or_equal:ends_at','know_before_you_go'=>'nullable|string','latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','facilities'=>'array','facilities.*'=>'exists:facilities,id'];} }
